    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.isAnimating = false;

                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupWheelNav();
                this.setupTouchNav();
                this.setupNavDots();
                this.updateState();
            }

            setupIntersectionObserver() {
                const options = { root: null, rootMargin: '0px', threshold: 0.5 };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');

                            // Update current slide index based on DOM
                            this.slides.forEach((slide, index) => {
                                if (slide === entry.target) {
                                    this.currentSlide = index;
                                    this.updateUI();
                                }
                            });
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));

                // Trigger first slide immediately
                if(this.slides[0]) this.slides[0].classList.add('visible');
            }

            goToSlide(index) {
                if (this.isAnimating || index < 0 || index >= this.slides.length) return;

                this.isAnimating = true;
                this.currentSlide = index;
                this.slides[this.currentSlide].scrollIntoView({ behavior: 'smooth' });

                setTimeout(() => { this.isAnimating = false; }, 800);
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    } else if (e.key === 'Home') {
                        e.preventDefault();
                        this.goToSlide(0);
                    } else if (e.key === 'End') {
                        e.preventDefault();
                        this.goToSlide(this.slides.length - 1);
                    }
                });
            }

            setupWheelNav() {
                document.addEventListener('wheel', (e) => {
                    if (this.isAnimating) return;
                    // Debounce wheel events
                    this.isAnimating = true;

                    if (e.deltaY > 50) {
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.deltaY < -50) {
                        this.goToSlide(this.currentSlide - 1);
                    } else {
                        this.isAnimating = false;
                    }

                    setTimeout(() => { this.isAnimating = false; }, 1000);
                }, { passive: true });
            }

            setupTouchNav() {
                let touchStartY = 0;
                let touchEndY = 0;

                document.addEventListener('touchstart', e => {
                    touchStartY = e.changedTouches[0].screenY;
                }, { passive: true });

                document.addEventListener('touchend', e => {
                    touchEndY = e.changedTouches[0].screenY;
                    this.handleSwipe();
                }, { passive: true });

                this.handleSwipe = () => {
                    if (this.isAnimating) return;
                    const threshold = 50;
                    if (touchEndY < touchStartY - threshold) {
                        this.goToSlide(this.currentSlide + 1); // Swipe up -> next
                    }
                    if (touchEndY > touchStartY + threshold) {
                        this.goToSlide(this.currentSlide - 1); // Swipe down -> prev
                    }
                };
            }

            setupNavDots() {
                const navContainer = document.getElementById('navDots');
                if (!navContainer) return;

                this.slides.forEach((_, index) => {
                    const dot = document.createElement('div');
                    dot.className = 'dot';
                    dot.title = `Slide ${index + 1}`;
                    dot.addEventListener('click', () => this.goToSlide(index));
                    navContainer.appendChild(dot);
                });

                this.dots = document.querySelectorAll('.dot');
            }

            updateUI() {
                // Update dots
                if (this.dots) {
                    this.dots.forEach((dot, index) => {
                        dot.classList.toggle('active', index === this.currentSlide);
                    });
                }

                // Update progress bar
                const progressBar = document.getElementById('progressBar');
                if (progressBar) {
                    const progress = ((this.currentSlide) / (this.slides.length - 1)) * 100;
                    progressBar.style.width = `${progress}%`;
                }
            }

            updateState() {
                this.updateUI();
            }
        }

        // Initialize on load
        window.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
